contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint v, bool shouldSucceed) public payable {
        require(tos.length > 0);
        require(caddress.code.length > 0);

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));

        bool allCallsWouldSucceed = true;
        for (uint i = 0; i < tos.length; i++) {
            (bool ok, bytes memory data) = caddress.call(abi.encodeWithSelector(id, from, tos[i], v));
            data;
            if (!ok) {
                allCallsWouldSucceed = false;
                break;
            }
        }

        bool reverted;
        try c.transfer(from, caddress, tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !allCallsWouldSucceed);
    }

    receive() external payable {}
}

